import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CiQ1TEvV.js";const u=JSON.parse('{"title":"TUI 命令","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/tui-commands.md","filePath":"zh/guide/tui-commands.md","lastUpdated":1785115728000}'),s={name:"zh/guide/tui-commands.md"};function n(l,t,i,o,c,p){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="tui-命令" tabindex="-1">TUI 命令 <a class="header-anchor" href="#tui-命令" aria-label="Permalink to &quot;TUI 命令&quot;">​</a></h1><p>Mneme 基于 Rich 的终端 UI 支持斜杠命令和键盘快捷键。</p><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/help</code></td><td>显示所有命令</td></tr><tr><td><code>/files</code></td><td>添加、删除、列出、监听或停止监听文件</td></tr><tr><td><code>/mode</code></td><td>切换 Standard RAG / Graph RAG</td></tr><tr><td><code>/alpha</code></td><td>设置 Graph RAG 融合权重</td></tr><tr><td><code>/settings</code></td><td>查看或更改 API 设置</td></tr><tr><td><code>/models</code></td><td>列出可用模型</td></tr><tr><td><code>/status</code></td><td>显示索引和服务状态</td></tr><tr><td><code>/clear</code></td><td>清除聊天历史</td></tr><tr><td><code>/quit</code></td><td>退出</td></tr></tbody></table><h2 id="文件管理示例" tabindex="-1">文件管理示例 <a class="header-anchor" href="#文件管理示例" aria-label="Permalink to &quot;文件管理示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/files watch /path/to/directory</span></span>
<span class="line"><span>/files list</span></span>
<span class="line"><span>/files stop</span></span>
<span class="line"><span>/files add /path/to/file.pdf</span></span>
<span class="line"><span>/files remove /path/to/file.pdf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>操作</th></tr></thead><tbody><tr><td><code>Ctrl+P</code></td><td>打开命令面板</td></tr><tr><td><code>Ctrl+L</code></td><td>切换侧边栏</td></tr><tr><td><code>Ctrl+N</code></td><td>新建会话</td></tr><tr><td><code>Ctrl+K</code></td><td>清除聊天</td></tr><tr><td><code>Ctrl+C</code></td><td>退出</td></tr></tbody></table><h2 id="模式切换" tabindex="-1">模式切换 <a class="header-anchor" href="#模式切换" aria-label="Permalink to &quot;模式切换&quot;">​</a></h2><p>使用 <code>/mode</code> 在 Standard RAG 和 Graph RAG 之间切换。从 Standard 切换到 Graph RAG 时，Mneme 会：</p><ol><li>显示确认提示</li><li>从当前索引构建知识图谱（带进度条）</li><li>切换检索模式</li></ol><p>切换回 Standard RAG 时，模式立即更改，无需重建。</p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>使用 <code>/settings</code> 查看和修改：</p><ul><li>API Key（安全遮蔽显示）</li><li>Base URL</li><li>LLM 模型</li><li>Temperature</li><li>Top-K Min / Max</li><li>Alpha（Graph RAG 权重）</li></ul><p>所有更改持久化到 <code>.env</code> 并立即生效。</p>`,16)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
